mapper.select:
SELECT COUNT(1)
FROM review r
WHERE r.dish_id = #{dishId}
  AND r.status = #{status}

SELECT r.id, r.user_id AS userId, su.nickname AS userNickname, su.avatar_url AS userAvatar, r.target_type AS targetType, r.dish_id AS targetId, r.dish_id AS dishId, d.name AS dishName, r.overall_score AS overallScore, r.taste_score AS tasteScore, r.portion_score AS portionScore, r.value_score AS valueScore, r.content, r.is_anonymous AS isAnonymous, r.like_count AS likeCount, r.created_at AS createdAt FROM review r INNER JOIN sys_user su ON su.id = r.user_id INNER JOIN dish d ON d.id = r.dish_id WHERE r.dish_id = #{dishId} AND r.status = #{status}
ORDER BY r.overall_score DESC, r.id DESC
ORDER BY r.overall_score ASC, r.id DESC
ORDER BY r.created_at DESC, r.id DESC
LIMIT #{offset}, #{size}

SELECT review_id AS reviewId, image_url AS imageUrl FROM review_image WHERE review_id IN
#{reviewId}
ORDER BY sort_order ASC, id ASC

SELECT review_id
FROM review_like
WHERE user_id = #{userId}
  AND review_id IN

    #{reviewId}

mapper.update:
UPDATE review
SET like_count = like_count + 1
WHERE id = #{id}

UPDATE review
SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
WHERE id = #{id}

UPDATE merchant
SET review_count = #{reviewCount},
    average_score = #{averageScore}
WHERE id = #{merchantId}
